mapper.select:
${pagingTop} SELECT homepage_id, writing_idx, participation_field, writing_type, user_name, school_name, school_year, user_phone, protector_phone, user_email, postcode, address_base, address_detailed, approval_status, delete_yn, add_id, add_date FROM WRITING_CONTEST WHERE homepage_id = #{homepage_id} AND delete_yn = 'N'
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY writing_idx DESC ${pagingBottom}

mapper.update:
UPDATE
	WRITING_CONTEST
SET
	delete_yn = 'Y',
	delete_id = #{delete_id}
WHERE
	homepage_id = #{homepage_id}
AND writing_idx = #{writing_idx}

UPDATE
	WRITING_CONTEST
SET
	approval_status = #{approval_status}
WHERE
	homepage_id = #{homepage_id}
AND writing_idx = #{writing_idx}
